CREATE TABLE public.employee_posts (
	id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
	name text NOT NULL,
	is_active boolean NOT NULL DEFAULT true,
	CHECK (btrim(name) <> '')
);

COMMENT ON TABLE public.employee_posts IS 'Employee post reference data.';
COMMENT ON COLUMN public.employee_posts.name IS 'Display name of the post.';

CREATE INDEX employee_posts_name_idx
	ON public.employee_posts USING btree (lower(name));

WITH required(code, description) AS (
	VALUES
		('employeePost.create', 'Создание должнности'),
		('employeePost.list', 'Просмотр списка должностей'),
		('employeePost.detail', 'Просмотр должнности'),
		('employeePost.update', 'Изменение должнности'),
		('employeePost.delete', 'Удаление должнности')
)
INSERT INTO public.permissions (code, description)
SELECT required.code, required.description
FROM required
ON CONFLICT (code) DO UPDATE
SET description = EXCLUDED.description;

WITH roles(role_id) AS (
	VALUES
		('admin'::public.role_types)
), required(permission_code) AS (
	VALUES
		('employeePost.create'),
		('employeePost.list'),
		('employeePost.detail'),
		('employeePost.update'),
		('employeePost.delete')
)
INSERT INTO public.role_permissions (role_id, permission_code)
SELECT roles.role_id, required.permission_code
FROM roles
CROSS JOIN required
ON CONFLICT DO NOTHING;

