	WHERE item.role_id = 'admin'::public.role_types
		AND item.user_id IS NULL
		AND item.parent_id IS NULL
		AND item.caption = 'Должности'
	ORDER BY item.id
	LIMIT 1
) AS parent ON true
WHERE route.name = 'employeePosts'
